INSERT INTO machine_forward_requests(id,forward_frame_id,side,request_frame_id,origin_machine_id,origin_session_id,connection_id,expected_holder_machine_id,project_id,phase,deadline_at,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,CAST(? AS INTEGER),CAST(? AS INTEGER),CAST(? AS INTEGER)) ON CONFLICT(forward_frame_id,side) DO UPDATE SET expected_holder_machine_id=excluded.expected_holder_machine_id,phase=excluded.phase,updated_at=excluded.updated_at;
